//@ts-check
/** Durable replication state shares the data transaction and capture settlement. */
import { stableStringify, deepFreeze } from '@jarenjs/core/object';
import { applyJSONPatch } from '@jarenjs/json/patch';
import { decodeJSONPointerSegment } from '@jarenjs/json/pointer';
import { utf8ByteLength } from '@jarenjs/core/string';
import { assertItemBytes, createCursor, drainPage } from './cursor.js';
import { chain, useStatementOnce } from './driver.js';
import { DbRuntimeError } from './errors.js';
import { refuseCancelled } from './cancellation.js';
import { normalizeReplication, normalizeReplicationSnapshot, normalizeFrontier, replicationIdentity, REPLICATION_DEFAULTS } from './replication-format.js';
import { REPLICATION_TABLES } from './replication-tables.js';
import { replicationSchema } from './dialects/replication.js';
import { readOptions, readOptionsOrNull } from './options.js';
import { compileJsonQuery } from '@jarenjs/json/query';
import { foreignKeyEdges } from './cascade.js';

/** The controls every replication call takes beside its own bounds. */
const CONTROL_OPTIONS = ['signal', 'deadline'];
// member order is not part of a row's value: the serialization sorts members
const equal = (a, b) => stableStringify(a) === stableStringify(b);
const position = (frontier, id) => Object.hasOwn(frontier, id) ? frontier[id] : 0;
const dominates = (a, b) => Object.entries(b).every(([id, seq]) => position(a, id) >= seq);
const fail = (code, reason) => { throw new DbRuntimeError(code, reason); };
const joinFrontiers = (a, b) => normalizeFrontier(Object.fromEntries([...new Set([...Object.keys(a), ...Object.keys(b)])]
  .map((id) => [id, Math.max(position(a, id), position(b, id))])));
const each = (items, fn) => {
  let i = 0;
  const next = () => {
    while (i < items.length) {
      const value = fn(items[i++]);
      if (value instanceof Promise) return value.then(next);
    }
    return null;
  };
  return next();
};

/** Canonical row order: how every envelope a store exports lists its
 * operations, and the order a reset starts from.
 * @param {{ table: string, key: string }} a @param {{ table: string, key: string }} b */
const canonical = (a, b) => {
  const x = JSON.stringify([a.table, a.key]);
  const y = JSON.stringify([b.table, b.key]);
  return x < y ? -1 : x > y ? 1 : 0;
};

/** A min-heap of operation positions: the earliest ready operation runs next. */
const positions = () => {
  /** @type {number[]} */
  const heap = [];
  return {
    get size() { return heap.length; },
    /** @param {number} at */
    push(at) {
      let child = heap.push(at) - 1;
      while (child > 0) {
        const parent = (child - 1) >> 1;
        if (heap[parent] <= at) break;
        heap[child] = heap[parent];
        child = parent;
      }
      heap[child] = at;
    },
    pop() {
      const top = heap[0];
      const last = /** @type {number} */ (heap.pop());
      if (heap.length > 0) {
        let parent = 0;
        for (;;) {
          let child = 2 * parent + 1;
          if (child >= heap.length) break;
          if (child + 1 < heap.length && heap[child + 1] < heap[child]) child += 1;
          if (heap[child] >= last) break;
          heap[parent] = heap[child];
          parent = child;
        }
        heap[parent] = last;
      }
      return top;
    },
  };
};

/**
 * The order replay writes a transaction's rows in, from the store's entity
 * mapping. A removal runs the replica's own `cascade` actions at once, and a
 * write is checked for uniqueness as it runs, while foreign-key checks wait
 * for the commit. So:
 * - a kept row (`before` and `after` both present) whose stored `cascade` key
 *   names a row the operations remove — directly, or through removed rows
 *   whose own cascading keys lead there — is written before each of those
 *   removals, which would otherwise delete it first. Each kept row gets one
 *   edge per removal on that path, so the edges grow as the kept rows times
 *   the path's depth, both within `maxOperations`;
 * - the operation that releases a value of an entity's unique slot (a
 *   one-to-one key, a unique member, a unique index) runs before the
 *   operation that takes it. A partial index holds the rows its condition is
 *   true for as the query engine answers it, which is what both engines'
 *   indexes hold; an edge too many is not harmless, since it can close a
 *   cycle the envelope does not have;
 * - otherwise the given order holds: the earliest operation whose
 *   predecessors have all run goes next. A cycle has no order: values rotated
 *   between rows, or a row moved off a removed parent that takes a value the
 *   removal releases (only a self-referencing table, or a cascading path back
 *   to the table, can form one). The earliest pending operation then goes
 *   next and the replay refuses — `JD2005` when it takes a value still held,
 *   `JD2104` when it is a removal that reaches a row which had to go first.
 * Collection documents and memberships meet neither rule and keep their order.
 * @param {any} mapping - the store's entity mapping, or `null`
 * @param {(table: string, column: string, value: any) => any} columnValue - a member as its column stores it
 * @returns {(operations: any[]) => any[]} over `{ table, key, before, after }`, `before` being the replica's row
 */
const replayOrder = (mapping, columnValue) => {
  const { outbound } = foreignKeyEdges(mapping);
  /** @type {Map<string, { cascades: any[], slots: { columns: string[], covers: ((doc: any) => boolean) | null }[] }>} */
  const tables = new Map();
  for (const [table, entity] of Object.entries(mapping?.entities ?? {})) {
    const cascades = (outbound.get(table) ?? []).filter((edge) => edge.kind === 'fk' && edge.onDelete === 'cascade');
    /** @type {{ columns: string[], covers: ((doc: any) => boolean) | null }[]} */
    const slots = [];
    const declared = new Set();
    /** @param {string[]} columns @param {any} [where] */
    const slot = (columns, where) => {
      const id = JSON.stringify([columns, where ?? null]);
      if (declared.has(id)) return;
      declared.add(id);
      if (where === undefined || where === null) {
        slots.push({ columns, covers: null });
        return;
      }
      // the index holds a row where the query engine answers its condition
      // true, a row lacking a member it reads included (a logical row omits a
      // null member, and the index reads that column's NULL alike). Should a
      // condition the store accepted not compile, every row counts: an extra
      // edge can only refuse an envelope, a missing one could let a moved row
      // take a value before its release
      let holds = null;
      try { holds = compileJsonQuery(where); }
      catch { holds = null; }
      const condition = holds;
      slots.push({ columns, covers: (doc) => condition === null || condition(doc) === true });
    };
    for (const fk of entity.foreignKeys ?? []) if (fk.unique) slot([fk.column]);
    for (const index of entity.indexes ?? []) if (index.unique) slot([index.property]);
    // an index over an expression keys no column's value: it has no slot, so a
    // value its function folds together is not ordered by it (MODEL-FORMAT §7A)
    for (const index of entity.entityIndexes ?? []) if (index.unique && index.expression === undefined) slot(index.columns, index.where);
    if (cascades.length > 0 || slots.length > 0) tables.set(table, { cascades, slots });
  }
  /** The rows a row's stored cascading keys name. @param {any} plan @param {any} doc @returns {string[]} */
  const parentsOf = (plan, doc) => (doc === null ? [] : plan.cascades.filter((edge) => doc[edge.column] != null)
    .map((edge) => JSON.stringify([edge.parent, String(doc[edge.column])])));
  /** The unique values a row holds, one string per covered slot whose columns hold no null.
   * @param {string} table @param {any} plan @param {any} doc @returns {Set<string>} */
  const valuesOf = (table, plan, doc) => {
    const values = new Set();
    if (doc === null) return values;
    for (const [at, slot] of plan.slots.entries()) {
      if (slot.covers !== null && !slot.covers(doc)) continue;
      const tuple = slot.columns.map((column) => (doc[column] === undefined || doc[column] === null ? null
        : columnValue(table, column, doc[column])));
      // NULL never collides
      if (tuple.every((value) => value !== null && value !== undefined)) values.add(JSON.stringify([table, at, tuple]));
    }
    return values;
  };

  return (operations) => {
    if (tables.size === 0) return operations;
    /** @type {Map<string, number>} */
    const removed = new Map();
    operations.forEach((op, at) => { if (op.after === null) removed.set(JSON.stringify([op.table, op.key]), at); });
    /** @type {number[][]} */
    const next = [];
    const waits = new Array(operations.length).fill(0);
    let edges = 0;
    /** @param {number} from @param {number} to */
    const precede = (from, to) => {
      if (from === to) return;
      (next[from] ??= []).push(to);
      waits[to] += 1;
      edges += 1;
    };
    /** @type {Map<string, number[]>} */
    const released = new Map();
    /** @type {Map<string, number[]>} */
    const taken = new Map();
    /** @param {Map<string, number[]>} map @param {string} value @param {number} at */
    const note = (map, value, at) => {
      const list = map.get(value);
      if (list === undefined) map.set(value, [at]);
      else list.push(at);
    };
    operations.forEach((op, at) => {
      const plan = tables.get(op.table);
      if (plan === undefined) return;
      if (op.before !== null && op.after !== null && removed.size > 0) {
        // every removal whose cascades would reach this row while it still names its old parent
        const queue = parentsOf(plan, op.before);
        const met = new Set();
        while (queue.length > 0) {
          const token = /** @type {string} */ (queue.pop());
          const removal = removed.get(token);
          if (removal === undefined || met.has(token)) continue;
          met.add(token);
          precede(at, removal);
          const parent = operations[removal];
          const parentPlan = tables.get(parent.table);
          if (parentPlan !== undefined) queue.push(...parentsOf(parentPlan, parent.before));
        }
      }
      if (plan.slots.length > 0) {
        const before = valuesOf(op.table, plan, op.before);
        const after = valuesOf(op.table, plan, op.after);
        for (const value of before) if (!after.has(value)) note(released, value, at);
        for (const value of after) if (!before.has(value)) note(taken, value, at);
      }
    });
    for (const [value, takers] of taken) {
      for (const from of released.get(value) ?? []) for (const to of takers) precede(from, to);
    }
    if (edges === 0) return operations;
    const ready = positions();
    operations.forEach((_, at) => { if (waits[at] === 0) ready.push(at); });
    const done = new Array(operations.length).fill(false);
    const order = [];
    let earliest = 0;
    while (order.length < operations.length) {
      let at;
      if (ready.size > 0) at = ready.pop();
      else {
        // a cycle, which no order replays: the earliest pending operation goes next
        while (done[earliest]) earliest += 1;
        at = earliest;
      }
      if (done[at]) continue;
      done[at] = true;
      order.push(operations[at]);
      for (const to of next[at] ?? []) {
        waits[to] -= 1;
        if (waits[to] === 0 && !done[to]) ready.push(to);
      }
    }
    return order;
  };
};

/** Pure preflight shared by store construction and the engine.
 * @param {any} options @returns {any} */
export function readReplicationOptions(options) {
  readOptions(options, ['replica', 'retention', 'maxOperations', 'maxBytes', 'resolver'], 'replication', 'JD0009');
  const config = { ...REPLICATION_DEFAULTS, ...options };
  replicationIdentity(config.replica, 1);
  for (const member of ['retention', 'maxOperations', 'maxBytes']) {
    if (!Number.isSafeInteger(config[member]) || config[member] < 1)
      throw new TypeError(`replication.${member} must be a positive safe integer`);
  }
  if (config.resolver !== undefined && (typeof config.resolver?.id !== 'string' || !config.resolver.id
    || typeof config.resolver.resolve !== 'function')) throw new TypeError('replication.resolver needs a stable id and pure resolve function');
  return config;
}

/** @param {any} options */
export function createReplicationEngine(options) {
  const { connection, rows, capture, model, now, bracket, mapping } = options;
  const config = readReplicationOptions(options.config);
  const replay = replayOrder(mapping, rows.columnValue);
  const dialect = connection.dialect;
  const p = (i) => dialect.parameterRef(i, 'replica');
  const schema = replicationSchema(dialect);
  const sql = (text, method = 'run', params = []) => useStatementOnce(connection, text, (s) => s[method](params));
  const state = () => chain(sql(`SELECT value FROM ${REPLICATION_TABLES.state} WHERE id = 1`, 'get'), (row) => JSON.parse(row.value));
  const saveState = (value) => sql(`UPDATE ${REPLICATION_TABLES.state} SET value = ${p(1)} WHERE id = 1`, 'run', [stableStringify(value)]);
  const rowState = (table, key) => chain(sql(`SELECT value, frontier FROM ${REPLICATION_TABLES.rows} WHERE name = ${p(1)} AND key = ${p(2)}`, 'get', [table, key]),
    (row) => row === undefined ? { value: null, frontier: {} } : { value: JSON.parse(row.value), frontier: JSON.parse(row.frontier) });
  const saveRow = (operation, frontier) => sql(`INSERT INTO ${REPLICATION_TABLES.rows} (name, key, value, frontier) VALUES (${p(1)}, ${p(2)}, ${p(3)}, ${p(4)}) `
    + 'ON CONFLICT(name, key) DO UPDATE SET value = excluded.value, frontier = excluded.frontier', 'run',
  [operation.table, operation.key, stableStringify(operation.after), stableStringify(frontier)]);
  const cancelled = (request) => refuseCancelled(request, now, {
    abortCode: 'JD2072', aborted: 'the next replication operation', passed: 'the next replication operation', ran: 'the transaction is not acknowledged',
  });
  const bounded = (document) => {
    if (document.operations.length > config.maxOperations) fail('JD2106', 'replication operation bound exceeded');
    assertItemBytes(utf8ByteLength(stableStringify(document)), config.maxBytes);
  };
  const receipt = (envelope) => sql(`INSERT INTO ${REPLICATION_TABLES.receipts} (id, payload) VALUES (${p(1)}, ${p(2)})`, 'run',
    [replicationIdentity(envelope.replica, envelope.seq), stableStringify(envelope)]);
  // Pull one row at a time and refuse before accumulating beyond shared credits.
  const collectBounded = async (query, params, map, request, credits) => {
    cancelled(request);
    return useStatementOnce(connection, query, async (statement) => {
      const cursor = createCursor({ streaming: 'row', barrier: null, signal: request?.signal, deadline: request?.deadline, now,
        open: () => statement.iterate(params), items: (row) => [map(row)] });
      const result = [];
      for await (const item of cursor) {
        if (++credits.count > config.maxOperations) fail('JD2106', 'replication read exceeds its row capacity');
        credits.bytes += utf8ByteLength(stableStringify(item)) + 1;
        assertItemBytes(credits.bytes, Math.min(request?.maxBytes ?? config.maxBytes, config.maxBytes));
        result.push(item);
      }
      return result;
    });
  };

  const ready = bracket(() => chain(dialect.replication?.initialize?.(connection), () =>
    chain(each(schema.create, (ddl) => connection.exec(ddl)), () =>
    chain(dialect.replication?.verify?.(connection, schema, options.managedTables ?? []), () =>
    chain(sql(`SELECT value FROM ${REPLICATION_TABLES.state} WHERE id = 1`, 'get'), (existing) => {
    if (existing !== undefined) {
      const saved = JSON.parse(existing.value);
      if (saved.replica !== config.replica || saved.model !== model)
        fail('JD2102', 'the durable replica identity or model revision disagrees with this open');
      return null;
    }
    return chain(rows.empty(), (empty) => {
      if (!empty) fail('JD2105', 'initialize replication on an empty store, then import an explicit snapshot');
      return chain(each(schema.tables, (table) => chain(sql(`SELECT 1 AS present FROM ${table.name} LIMIT 1`, 'get'), (row) => {
        if (row !== undefined) fail('JD2104', 'replication metadata exists without its durable identity');
      })), () => sql(`INSERT INTO ${REPLICATION_TABLES.state} (id, value) VALUES (1, ${p(1)})`, 'run',
        [stableStringify({ replica: config.replica, model, frontier: {} })]));
    });
  })))));

  /** Convert net capture patches against durable before-images, inside commit. */
  const commit = (patch, context) => {
    if (patch.length === 0) return null;
    const grouped = new Map();
    for (const operation of patch) {
      const segments = operation.path.split('/').slice(1).map(decodeJSONPointerSegment);
      const identity = JSON.stringify(segments.slice(0, 2));
      if (!grouped.has(identity)) grouped.set(identity, { table: segments[0], key: segments[1], patch: [] });
      const prefix = operation.path.split('/').slice(0, 3).join('/');
      grouped.get(identity).patch.push({ ...operation, path: operation.path.slice(prefix.length),
        ...(operation.from === undefined ? {} : { from: operation.from.slice(prefix.length) }) });
    }
    if (grouped.size > config.maxOperations) fail('JD2106', 'replication operation bound exceeded');
    if (context?.replication === true) {
      // Applying metadata has already installed the intended final images.
      // Any undeclared cascade must roll back with the envelope, never escape
      // its receipt and leave an acknowledged row silently missing.
      return each([...grouped.values()], (entry) => chain(rowState(entry.table, entry.key), (expected) =>
        chain(rows.read(entry.table, entry.key), (actual) => {
          if (!equal(actual ?? null, expected.value)) fail('JD2104', 'replication caused an undeclared row side effect');
        })));
    }
    return chain(state(), (saved) => {
      const operations = [];
      return chain(each([...grouped.values()].sort(canonical), (entry) => chain(rowState(entry.table, entry.key), (old) => {
        const after = entry.patch.length === 1 && entry.patch[0].op === 'remove' && entry.patch[0].path === ''
          ? null : applyJSONPatch(old.value, entry.patch);
        return chain(rows.read(entry.table, entry.key), (actual) => {
          // a removal that still reads its row: the transaction stored it
          // again under another spelling of its key (an instant's), which a
          // replica's history names as another row
          if (after === null && actual != null) {
            fail('JD2104', `the row '${entry.key}' of '${entry.table}' was stored again under another spelling of its `
              + 'key, which replication cannot carry — store it under the spelling it holds');
          }
          if (!equal(actual ?? null, after)) fail('JD2104', 'capture disagrees with the durable replica before-image');
          // a row stored again with the document it had (deleted and stored
          // again, a membership unlinked and linked again) changed nothing a
          // replica holds: rows replicate without their order. A row neither
          // side holds is still an operation, which the envelope refuses
          if (old.value === null || !equal(old.value, after))
            operations.push({ table: entry.table, key: entry.key, before: old.value, after });
        });
      })), () => {
        if (operations.length === 0) return null;
        const seq = position(saved.frontier, config.replica) + 1;
        const envelope = normalizeReplication({ $replication: '0.1', replica: config.replica, seq,
          frontier: saved.frontier, model, operations });
        bounded(envelope);
        const frontier = joinFrontiers(saved.frontier, { [config.replica]: seq });
        return chain(each(operations, (operation) => saveRow(operation, frontier)), () => chain(receipt(envelope), () =>
          chain(sql(`INSERT INTO ${REPLICATION_TABLES.outbox} (seq, payload) VALUES (${p(1)}, ${p(2)})`, 'run', [seq, stableStringify(envelope)]), () =>
            chain(sql(`DELETE FROM ${REPLICATION_TABLES.outbox} WHERE seq <= ${p(1)}`, 'run', [seq - config.retention]), () =>
              saveState({ ...saved, frontier })))));
      });
    });
  };

  /** All checks precede writes; conflict evidence commits without advancing a frontier. */
  const apply = (input, request, transaction) => {
    readOptionsOrNull(request, CONTROL_OPTIONS, 'replication.apply');
    const envelope = normalizeReplication(input);
    bounded(envelope);
    cancelled(request);
    if (envelope.model !== model) fail('JD2102', 'replication model revision mismatch');
    const identity = replicationIdentity(envelope.replica, envelope.seq);
    return transaction(async () => {
      capture.setContext({ replication: true });
      cancelled(request);
      const saved = await state();
      const previous = await sql(`SELECT payload FROM ${REPLICATION_TABLES.receipts} WHERE id = ${p(1)}`, 'get', [identity]);
      if (previous !== undefined) {
        if (previous.payload !== stableStringify(envelope)) fail('JD2101', 'the envelope identity already has a different payload');
        return { status: 'duplicate', frontier: saved.frontier, conflicts: [] };
      }
      const claim = await sql(`SELECT payload FROM ${REPLICATION_TABLES.claims} WHERE id = ${p(1)}`, 'get', [identity]);
      if (claim !== undefined && claim.payload !== stableStringify(envelope))
        fail('JD2101', 'a conflicted envelope identity already has a different payload');
      const seen = position(saved.frontier, envelope.replica);
      if (envelope.seq <= seen) fail('JD2105', 'a snapshot covers this envelope but its receipt is unavailable; reset is required');
      if (envelope.seq !== seen + 1 || !dominates(saved.frontier, envelope.frontier))
        fail('JD2100', 'a sequence or causal gap requires missing history or an explicit reset');
      if (envelope.replica === config.replica) fail('JD2101', 'a replica cannot accept an unknown envelope under its own identity');
      const conflicts = [];
      const chosen = [];
      for (const operation of envelope.operations) {
        cancelled(request);
        const local = await rowState(operation.table, operation.key);
        const actual = await rows.read(operation.table, operation.key) ?? null;
        if (!equal(actual, local.value)) fail('JD2104', 'a row was written outside its replication history');
        let after = operation.after;
        if (!equal(actual, operation.before) && !equal(actual, operation.after)) {
          if (dominates(envelope.frontier, local.frontier)) fail('JD2104', 'the operation before-image disagrees with its causal base');
          const evidence = { envelope: identity, table: operation.table, key: operation.key,
            base: operation.before, local: { value: actual, frontier: local.frontier },
            remote: { value: operation.after, replica: envelope.replica, seq: envelope.seq, frontier: envelope.frontier },
            resolver: config.resolver?.id ?? null, resolution: null };
          if (config.resolver) {
            const input = structuredClone(evidence);
            let decision;
            try { decision = config.resolver.resolve(deepFreeze(input)); }
            catch (cause) { throw new DbRuntimeError('JD2103', 'the conflict resolver failed', { cause }); }
            if (decision && typeof decision.then === 'function') {
              Promise.resolve(decision).catch(() => {});
              fail('JD2103', 'a conflict resolver must be synchronous');
            }
            if (!decision || !['local', 'remote', 'merged'].includes(decision.action))
              fail('JD2103', 'a pure resolver must return local, remote or merged synchronously');
            after = decision.action === 'local' ? actual : decision.action === 'remote' ? operation.after : decision.value;
            // Reuse the document grammar for merged values, including finite JSON.
            if (!equal(after, actual)) normalizeReplication({ ...envelope, operations: [{ ...operation, before: actual, after }] });
            evidence.resolution = { action: decision.action, value: after };
          }
          conflicts.push(evidence);
        }
        chosen.push({ ...operation, before: actual, after });
      }
      bounded({ ...envelope, operations: chosen });
      assertItemBytes(utf8ByteLength(stableStringify(conflicts)), config.maxBytes);
      for (const conflict of conflicts) {
        await sql(`INSERT INTO ${REPLICATION_TABLES.conflicts} (id, evidence) VALUES (${p(1)}, ${p(2)}) ON CONFLICT(id) DO UPDATE SET evidence = excluded.evidence`,
          'run', [JSON.stringify([identity, conflict.table, conflict.key]), stableStringify(conflict)]);
      }
      if (conflicts.length > 0 && !config.resolver) {
        if (claim === undefined) await sql(`INSERT INTO ${REPLICATION_TABLES.claims} (id, payload) VALUES (${p(1)}, ${p(2)})`, 'run', [identity, stableStringify(envelope)]);
        return { status: 'conflict', frontier: saved.frontier, conflicts };
      }
      // Canonical capture order is independent of FK topology; defer constraints
      // until all rows of the logical transaction have reached their final state,
      // in the order the replica's own cascades and unique indexes need
      await connection.exec(connection.dialect.tx.deferForeignKeys);
      for (const operation of replay(chosen)) {
        cancelled(request);
        if (!equal(operation.before, operation.after)) await rows.write(operation);
      }
      for (const operation of chosen) {
        if (!equal(await rows.read(operation.table, operation.key) ?? null, operation.after))
          fail('JD2104', 'the stored logical row differs from the requested replicated value');
      }
      const frontier = joinFrontiers(saved.frontier, { [envelope.replica]: envelope.seq });
      for (const operation of chosen) await saveRow(operation, frontier);
      await receipt(envelope);
      await saveState({ ...saved, frontier });
      cancelled(request);
      return { status: 'applied', frontier, conflicts };
    }, request);
  };

  const page = async (request) => {
    request ??= {};
    readOptionsOrNull(request, ['after', 'limit', 'maxBytes', 'signal', 'deadline'], 'replication.page');
    const { after = 0, limit = 100, maxBytes = config.maxBytes } = request;
    if (!Number.isSafeInteger(after) || after < 0 || !Number.isSafeInteger(limit) || limit < 1
      || !Number.isSafeInteger(maxBytes) || maxBytes < 1) throw new TypeError('replication.page needs safe after, limit and maxBytes bounds');
    cancelled(request);
    const saved = await state();
    const highWatermark = position(saved.frontier, config.replica);
    const floor = await sql(`SELECT min(seq) AS lo FROM ${REPLICATION_TABLES.outbox}`, 'get');
    const earliestAvailable = floor.lo === null ? null : Number(floor.lo);
    const bounds = { earliestAvailable, highWatermark };
    if (after > highWatermark || after + 1 < (earliestAvailable ?? highWatermark + 1))
      return { items: [], ...bounds, resetRequired: true, hasMore: false };
    cancelled(request);
    const page = await useStatementOnce(connection,
      `SELECT payload FROM ${REPLICATION_TABLES.outbox} WHERE seq > ${p(1)} ORDER BY seq LIMIT ${p(2)}`, (statement) => {
        const cursor = createCursor({ streaming: 'row', barrier: null, signal: request.signal, deadline: request.deadline, now,
          open: () => statement.iterate([after, limit + 1]),
          items: (row) => [{ envelope: JSON.parse(row.payload), bytes: utf8ByteLength(row.payload) }] });
        return drainPage(cursor, { limit, maxBytes: Math.min(maxBytes, config.maxBytes), after,
          sizeOf: (item) => item.bytes, continuationOf: (item) => item.envelope.seq });
      });
    return { items: page.items.map((item) => item.envelope), ...bounds, next: page.continuation ?? after,
      bytes: page.items.reduce((sum, item) => sum + item.bytes, 0), resetRequired: false, hasMore: page.hasMore };
  };
  const snapshot = async (request) => {
    request ??= {};
    readOptionsOrNull(request, ['maxBytes', 'signal', 'deadline'], 'replication.snapshot');
    const maxBytes = request.maxBytes ?? config.maxBytes;
    if (!Number.isSafeInteger(maxBytes) || maxBytes < 1) throw new TypeError('snapshot.maxBytes must be a positive safe integer');
    cancelled(request);
    const saved = await state();
    const credits = { count: 0, bytes: 0 };
    const values = await collectBounded(`SELECT name, key, value, frontier FROM ${REPLICATION_TABLES.rows} ORDER BY name, key LIMIT ${p(1)}`, [config.maxOperations + 1],
      (row) => ({ table: row.name, key: row.key, value: JSON.parse(row.value), frontier: JSON.parse(row.frontier) }), request, credits);
    const receipts = await collectBounded(`SELECT payload FROM ${REPLICATION_TABLES.receipts} ORDER BY id LIMIT ${p(1)}`, [config.maxOperations + 1],
      (row) => JSON.parse(row.payload), request, credits);
    const document = normalizeReplicationSnapshot({ $replicationSnapshot: '0.1', model, frontier: saved.frontier,
      rows: values, receipts });
    assertItemBytes(utf8ByteLength(stableStringify(document)), Math.min(maxBytes, config.maxBytes));
    cancelled(request);
    return document;
  };
  const reset = (input, request, transaction) => {
    readOptionsOrNull(request, CONTROL_OPTIONS, 'replication.reset');
    const document = normalizeReplicationSnapshot(input);
    if (document.model !== model) fail('JD2102', 'snapshot model revision mismatch');
    if (document.rows.length + document.receipts.length > config.maxOperations) fail('JD2106', 'snapshot exceeds the bounded reset capacity');
    assertItemBytes(utf8ByteLength(stableStringify(document)), config.maxBytes);
    for (const row of document.rows) if (!dominates(document.frontier, row.frontier)) fail('JD2104', 'snapshot row is ahead of its frontier');
    const receipts = new Map();
    for (const envelope of document.receipts) {
      if (envelope.model !== model || !dominates(document.frontier, { ...envelope.frontier, [envelope.replica]: envelope.seq }))
        fail('JD2104', 'snapshot receipt is ahead of its frontier or names another model');
      receipts.set(replicationIdentity(envelope.replica, envelope.seq), envelope);
    }
    // A frontier must never hide an unproven receipt gap.
    const counts = new Map();
    for (const envelope of receipts.values()) counts.set(envelope.replica, (counts.get(envelope.replica) ?? 0) + 1);
    for (const [replica, seq] of Object.entries(document.frontier)) if ((counts.get(replica) ?? 0) !== seq)
      fail('JD2104', 'snapshot receipts do not cover the complete frontier');
    return transaction(async () => {
      capture.setContext({ replication: true });
      cancelled(request);
      const saved = await state();
      if (!dominates(document.frontier, saved.frontier)) fail('JD2105', 'reset would discard acknowledged local history');
      const credits = { count: 0, bytes: 0 };
      const localReceipts = await collectBounded(`SELECT id, payload FROM ${REPLICATION_TABLES.receipts} LIMIT ${p(1)}`, [config.maxOperations + 1],
        (row) => row, request, credits);
      for (const local of localReceipts) if (stableStringify(receipts.get(local.id)) !== local.payload)
        fail('JD2101', 'snapshot rewrites an acknowledged envelope identity');
      const localRows = await collectBounded(`SELECT name, key, value FROM ${REPLICATION_TABLES.rows} LIMIT ${p(1)}`, [config.maxOperations + 1],
        (row) => row, request, credits);
      const desired = new Map(document.rows.map((row) => [JSON.stringify([row.table, row.key]), row]));
      const operations = new Map(localRows.map((row) => [JSON.stringify([row.name, row.key]),
        { table: row.name, key: row.key, before: JSON.parse(row.value), after: null }]));
      for (const [key, row] of desired) operations.set(key, { table: row.table, key: row.key,
        before: operations.get(key)?.before ?? null, after: row.value });
      await connection.exec(connection.dialect.tx.deferForeignKeys);
      for (const operation of operations.values()) {
        cancelled(request);
        if (!equal(await rows.read(operation.table, operation.key) ?? null, operation.before))
          fail('JD2104', 'reset found a row outside its replication history');
      }
      for (const operation of replay([...operations.values()].sort(canonical))) {
        cancelled(request);
        if (!equal(operation.before, operation.after)) await rows.write(operation);
      }
      for (const operation of operations.values()) if (!equal(await rows.read(operation.table, operation.key) ?? null, operation.after))
        fail('JD2104', 'reset did not store the requested logical state');
      await sql(`DELETE FROM ${REPLICATION_TABLES.rows}`);
      for (const row of document.rows) await saveRow({ ...row, after: row.value }, row.frontier);
      for (const envelope of receipts.values()) if (!localReceipts.some((local) => local.id === replicationIdentity(envelope.replica, envelope.seq))) await receipt(envelope);
      await sql(`DELETE FROM ${REPLICATION_TABLES.outbox}`);
      await saveState({ ...saved, frontier: document.frontier });
      cancelled(request);
      return { status: 'reset', frontier: document.frontier };
    }, request);
  };
  return { ready, commit, apply, page, snapshot, reset,
    frontier: () => chain(state(), (saved) => saved.frontier),
    conflicts: (request) => {
      request ??= {};
      readOptionsOrNull(request, ['limit', 'maxBytes', 'signal', 'deadline'], 'replication.conflicts');
      const limit = request.limit ?? 100;
      if (!Number.isSafeInteger(limit) || limit < 1) throw new TypeError('conflicts.limit must be a positive safe integer');
      if (request.maxBytes !== undefined && (!Number.isSafeInteger(request.maxBytes) || request.maxBytes < 1))
        throw new TypeError('conflicts.maxBytes must be a positive safe integer');
      cancelled(request);
      return collectBounded(`SELECT evidence FROM ${REPLICATION_TABLES.conflicts} ORDER BY id LIMIT ${p(1)}`, [Math.min(limit, config.maxOperations)],
        (row) => JSON.parse(row.evidence), request, { count: 0, bytes: 1 });
    },
  };
}
